<script lang="ts">
  import { Schema } from 'effect'; import { onMount } from 'svelte'; import Page from '@/lib/components/dashboard/Page.svelte'; import { dashboardJson,jsonRequest } from '@/lib/components/dashboard/api'
  const Subscriber=Schema.Struct({id:Schema.String,email:Schema.String,name:Schema.NullOr(Schema.String),source:Schema.NullOr(Schema.String),unsubscribedAt:Schema.NullOr(Schema.String),createdAt:Schema.String}); const Response=Schema.Struct({subscribers:Schema.Array(Subscriber)}); let subscribers=$state<ReadonlyArray<typeof Subscriber.Type>>([]),message=$state('')
  onMount(async()=>{try{subscribers=(await dashboardJson(Response,'/api/admin/newsletter-subscribers')).subscribers}catch{message='Could not load subscribers.'}})
  let mixSlug=$state(''),testRecipient=$state(''),artistName=$state(''); const SendResponse=Schema.Struct({success:Schema.Boolean,sentTo:Schema.Array(Schema.String),emailIds:Schema.Array(Schema.String),message:Schema.String})
  async function send(test:boolean){if(!test&& !confirm(`Broadcast ${mixSlug} to all opted-in subscribers?`))return;try{const result=test?await dashboardJson(SendResponse,'/api/email/send-mix-notification',jsonRequest('POST',{mixSlug,recipients:[testRecipient],metadata:{artistName}})):await dashboardJson(SendResponse,'/api/email/send-mix-notification',jsonRequest('POST',{mixSlug,metadata:{artistName}}));message=`${result.message} (${result.sentTo.length} recipients)`}catch{message='Send failed.'}}
</script>
<Page title="Newsletter" description="View the audience and send published mix notifications."><form class="grid gap-3 rounded border p-4 sm:grid-cols-3" onsubmit={(e)=>e.preventDefault()}><label>Published mix slug<input required class="block w-full rounded border bg-background p-2" bind:value={mixSlug}/></label><label>Artist name (optional)<input class="block w-full rounded border bg-background p-2" bind:value={artistName}/></label><label>Test recipient<input class="block w-full rounded border bg-background p-2" type="email" bind:value={testRecipient}/></label><div class="space-x-2 sm:col-span-3"><button type="button" class="rounded border px-4 py-2" disabled={!mixSlug||!testRecipient} onclick={()=>void send(true)}>Send test</button><button type="button" class="rounded bg-foreground px-4 py-2 text-background" disabled={!mixSlug} onclick={()=>void send(false)}>Broadcast</button></div></form><div class="overflow-x-auto rounded border"><table class="w-full text-left text-sm"><thead><tr class="bg-muted"><th class="p-3">Email</th><th>Name</th><th>Source</th><th>Status</th><th>Subscribed</th></tr></thead><tbody>{#each subscribers as subscriber}<tr class="border-t"><td class="p-3">{subscriber.email}</td><td>{subscriber.name??'—'}</td><td>{subscriber.source??'—'}</td><td>{subscriber.unsubscribedAt?'Unsubscribed':'Active'}</td><td>{new Date(subscriber.createdAt).toLocaleDateString()}</td></tr>{/each}</tbody></table></div>{#if message}<p>{message}</p>{/if}</Page>
